In this paper, we consider the constrained convex programming
\begin{equation}\label{eq:ccp}
\Min_{\vx\in\cX} f_0(\vx), \st \vA\vx=\vb, f_i(\vx)\le 0, i=1,\ldots, m,
\end{equation}
where $\cX\subseteq\RR^n$ is a closed convex set, $\vA$ and $\vb$ are respectively given matrix and vector, and $f_i$ is a convex function for every $i=0,1,\ldots,m$. Any convex optimization problem can be written in the standard form of \eqref{eq:ccp}. It appears in many areas including statistics, machine learning, data mining, engineering, signal processing, finance, operations research, and so on. 


We will assume composite convex structure on \eqref{eq:ccp}. More specifically, we assume \begin{equation}\label{eq:f0}
f_0(\vx)=g(\vx)+h(\vx),
\end{equation} 
where $g$ is a Lipschitz differentiable convex function, and $h$ is a simple\footnote{By ``simple'', we mean the proximal mapping of $h$ is easy to evaluate, i.e., it is easy to find a solution to $\min_{\vx\in\cX} h(\vx) + \frac{1}{2\gamma}\|\vx-\hat{\vx}\|^2$ for any $\hat{\vx}$ and $\gamma>0$.} (possibly nondifferentiable) convex function. Also, $f_i$ is convex and Lipschitz differentiable for every $i\in [m]$, namely, there are constants $L_0,L_1,\ldots, L_m$ such that
\begin{subequations}\label{eq:lip-gf}
\begin{align}
\|\nabla g(\hat{\vx})-\nabla g(\tilde{\vx})\|\le L_0\|\hat{\vx}-\tilde{\vx}\|,\,&\forall\, \hat{\vx}, \tilde{\vx} \in \dom(h)\cap \cX,\label{eq:lip-g}\\
\|\nabla f_i(\hat{\vx})-\nabla f_i(\tilde{\vx})\|\le L_i\|\hat{\vx}-\tilde{\vx}\|,\,& \forall\, \hat{\vx}, \tilde{\vx} \in \dom(h) \cap \cX, \forall i\in [m].\label{eq:lip-f}
\end{align} 
\end{subequations}
In addition, we assume the boundedness of $\dom(h)\cap\cX$ and denote its diameter as 
$$D=\Max_{\hat{\vx},\tilde{\vx}\in \dom(h)\cap\cX}\|\hat{\vx}-\tilde{\vx}\|.$$


\begin{equation}\label{eq:def-psi}
\psi_\beta(u,v) = \left\{\begin{array}{ll}uv+\frac{\beta}{2}u^2,\,&\text{ if }\beta u +v \ge0,\\[0.2cm]
-\frac{v^2}{2\beta},\,&\text{ if }\beta u +v < 0.\end{array}\right.
\end{equation}
Let
$$\Psi_\beta(\vx,\vz)=\sum_{i=1}^m\psi_\beta(f_i(\vx),z_i),$$
and we obtain the classical AL function of \eqref{eq:ccp}:
\begin{equation}\label{eq:aug-fun}
\cL_\beta(\vx,\vy,\vz) = f_0(\vx) + \vy^\top(\vA\vx-\vb) + \frac{\beta}{2}\|\vA\vx-\vb\|^2 + \Psi_\beta(\vx,\vz).
\end{equation}


\begin{algorithm}[h]
\caption{Inexact augmented Lagrangian method for \eqref{eq:ccp}}\label{alg:ialm}
\DontPrintSemicolon
\textbf{Initialization:} choose $\vx^0, \vy^0, \vz^0$ and $\{\beta_k,\rho_k\}$\;
\For{$k=0,1,\ldots$}{
Find $\vx^{k+1}\in\cX$ such that 
\begin{equation}\label{eq:ialm-x}
\cL_{\beta_k}(\vx^{k+1}, \vy^k , \vz^k  ) \le \min_{\vx\in\cX} \cL_{\beta_k}(\vx, \vy^k , \vz^k  ) + \vareps_k.
\end{equation}

Update $\vy$ and $\vz$ by
\begin{align}
\vy^{k+1} =&~\vy^k  + \rho_k (\vA\vx^{k+1}-\vb),\label{eq:alm-y}\\
z^{k+1} _i=&~z_i^k+\rho_k \cdot\max\left(-\frac{z_i^k}{\beta_k}, f_i(\vx^{k+1})\right), i=1,\ldots, m.\label{eq:alm-z}
\end{align}
}
\end{algorithm}

We use italic letters $a, c, B, L,\ldots,$ for scalars, bold lower-case letters $\vx,\vy,\vz,\ldots$ for vectors, and bold upper-case letters $\vA,\vB,\ldots$ for matrices. $z_i$ denotes the $i$-th entry of a vector $\vz$. We use $\vzero$ to denote a vector of all zeros, and its size is clear from the context. $[m]$ denotes the set $\{1,2,\ldots,m\}$ for any positive integer $m$. Given a real number $a$, we let $[a]_+=\max(0,a)$ and $\lceil a\rceil$ be the smallest integer that is no less than $a$. For a vector $\va$, $[\va]_+$ takes the positive part of $\va$ in a component-wise manner. $\|\va\|$ denotes the Euclidean norm of a vector $\va$ and $\|\vA\|$ the spectral norm of a matrix $\vA$. %By $p(k)\lesssim q(k)$, we mean $\limsup_k\frac{p(k)}{q(k)} \le 1$, i.e., $p(k)$ is dominated by $q(k)$. Given a symmetric positive definite (SPD) matrix $\vP$, we denote $\|\cdot\|_\vP$ as $\vP$-weighted norm, i.e., $\|\vw\|_\vP=\sqrt{\vw^\top \vP \vw}$ . If $\vP=\vI$, we simply write it as $\|\cdot\|$. 

We denote $\vell$ as the vector consisting of $L_i, i\in [m]$, where $L_i$ is the Lipschitz constant of $\nabla f_i$ in \eqref{eq:lip-f}. Also we let $\vf$ be the vector function with $f_i$ as the $i$-th component scalar function. That is 
\begin{equation}\label{eq:vec-ell}
\vell=[L_1,\ldots,L_m], \quad \vf(\vx)=[f_1(\vx),\ldots, f_m(\vx)].
\end{equation}
Given a convex function $f$, $\tilde{\nabla}f(\vx)$ represents one subgradient of $f$ at $\vx$, namely,
$$f(\hat{\vx})\ge f(\vx) + \langle \tilde{\nabla} f(\vx), \hat{\vx}-\vx\rangle,\,\forall\, \hat{\vx},$$ and $\partial f(\vx)$ denotes its subdifferential, i.e., the set of all subgradients. When $f$ is differentiable, we simply write its subgradient as $\nabla f(\vx)$. For a convex set $\cX$, we use $\iota_\cX$ as its indicator function, i.e., 
$$\iota_\cX(\vx)=\left\{\begin{array}{ll}0,&\text{ if }\vx\in\cX,\\+\infty,&\text{ if }\vx\not\in\cX,\end{array}\right.$$
and $\cN_\cX(\vx)=\partial \iota_\cX(\vx)$ as its normal cone at $\vx\in \cX$. 


\begin{definition}[$\vareps$-optimal solution]\label{def:eps-opt}
Let $f_0^*$ be the optimal value of \eqref{eq:ccp}. Given $\vareps\ge 0$, a point $\vx\in\cX$ is called an $\vareps$-optimal solution to \eqref{eq:ccp} if 
$$|f_0(\vx)-f_0^*| \le \vareps,\text{ and }\|\vA\vx-\vb\|+\big\| [\vf(\vx)]_+\big\| \le \vareps.$$
\end{definition}

A point $(\vx,\vy,\vz)$ satisfies the Karush-Kuhn-Tucker (KKT) conditions for \eqref{eq:ccp} if
\begin{subequations}\label{eq:kkt}
\begin{align}
0\in \partial f_0(\vx) +\cN_\cX(\vx) + \vA^\top \vy + \sum_{i=1}^m z_i \nabla f_i(\vx), \label{eq:kkt-1st}&\\
\vA\vx = \vb, \quad \vx\in \cX, \label{eq:kkt-res}&\\
z_i\ge0, \quad f_i(\vx)\le 0,\quad z_if_i(\vx)=0, \forall i\in [m]. \label{eq:kkt-cp}
\end{align}
\end{subequations}
From the convexity of $f_i$'s, if $(\vx^*,\vy^*,\vz^*)$ is a KKT point, then
\begin{equation}\label{eq:opt}
f_0(\vx)-f_0(\vx^*)+\langle \vy^*, \vA\vx-\vb\rangle + \sum_{i=1}^m z^*_i f_i(\vx) \ge 0,\, \forall\, \vx\in\cX.
\end{equation}


In this subsection, we review Nesterov's optimal first-order method for composite convex programs. The method will be used to approximately solve $\vx$-subproblems in Algorithm \ref{alg:ialm}. It aims at finding a solution of the following problem
\begin{equation}\label{eq:comp-prob}
\Min_\vx \phi(\vx) + \psi(\vx),
\end{equation}
where $\phi$ is a Lipschitz differentiable and strongly convex function with gradient Lipschitz constant $L_\phi$ and strong convexity modulus $\mu\ge0$, and $\psi$ is a simple (possibly nondifferentiable) closed convex function. Algorithm \ref{alg:apg} summarizes the method. Here, for simplicity, we assume $L_\phi$ and $\mu$ are known. The method does not require the value of $L_\phi$ but can estimate it by backtracking. In addition, it only requires a lower estimate of $\mu$; see \cite{nesterov2013gradient} for example.  %For our purpose, we will have $\mu=1$; see the problem \eqref{eq:ipalm-x} in Algorithm \ref{alg:ipalm}.


\begin{algorithm}\caption{Nesterov's optimal first-order method for \eqref{eq:comp-prob}}\label{alg:apg}
\textbf{Initialization:} choose $\hat{\vx}^0=\vx^0$, $\alpha_0\in (0,1]$, and let $q=\frac{\mu}{L_\phi}$\; 
\For{$k=0,1,\ldots, $}{
Let 
$$\vx^{k+1}=\argmin_{\vx} \langle \nabla \phi(\hat{\vx}^k), \vx\rangle + \frac{L_\phi}{2}\|\vx-\hat{\vx}^k\|^2+\psi(\vx).$$

Set $$\alpha_{k+1}=\frac{q-\alpha_k^2+\sqrt{(q-\alpha_k^2)^2+4\alpha_k^2}}{2},$$ and
$$\hat{\vx}^{k+1}=\vx^{k+1}+\frac{\alpha_k(1-\alpha_k)}{\alpha_k^2+\alpha_{k+1}}(\vx^{k+1}-\vx^k ).$$
}
\end{algorithm}

\begin{assumption}\label{assump-kkt}
There exists a point $(\vx^*,\vy^*,\vz^*)$ satisfying the KKT conditions in \eqref{eq:kkt}.
\end{assumption}

\begin{assumption}\label{assump-wd-ialm}
For every $k$, there is $\vx^{k+1}$ satisfying \eqref{eq:ialm-x}.
\end{assumption}

Let the smooth part of $\cL_\beta$ be denoted as
$$F_\beta(\vx,\vy,\vz) = \cL_\beta(\vx,\vy,\vz) - h(\vx).$$
Based on \eqref{eq:lip}, we are able to show Lipschitz continuity of $\nabla_\vx F_\beta(\vx,\vy,\vz)$ with respect to $\vx$ for every $(\vy,\vz)$.


Given $\vareps>0$, we set $\{\beta_k\}$ and $\{\rho_k\}$ according to one of the follows:

\begin{setting}[constant penalty]\label{set-penalty} Let $K$ be a positive integer number and $C_\beta$ a positive real number. Set $$\rho_k=\beta_k=\frac{C_\beta}{K\vareps},\,\forall \, 0\le k < K.$$ 
%where 
%\begin{equation}\label{eq:set-penalty}
%C_*=\max\left(4\|\vy^*\|^2+4\|\vz^*\|^2, (1+\|\vy^*\|)^2+\|\vone+\vz^*\|^2\right).
%\end{equation}
\end{setting}

\begin{setting}[geometrically increasing penalty]\label{set-ialm} Let $K$ be a positive integer number, $C_\beta$ a positive real number, and $\sigma>1$. Set 
\begin{equation}\label{eq:def-beta-g}
\beta_g = \frac{C_\beta}{\vareps}\frac{\sigma-1}{\sigma^K-1},
\end{equation}
and
$$ \rho_k=\beta_k=\beta_g\sigma^k, \,\forall\, 0\le k < K.$$ 
%\begin{equation}\label{eq:set-ialm}
%\beta_g = \frac{C^*}{\vareps}\frac{\sigma-1}{\sigma^K-1}
%\end{equation}
%where $C_*$ is given in \eqref{eq:set-penalty}.
\end{setting}


\textbf{``Optimal'' subproblem accuracy parameters.} If $t_k$ gradient evaluations are required to produce $\vx^{k+1}$, then the total number of gradient evaluations is 
$T_K=\sum_{k=0}^{K-1}t_k$ to generate $\{\vx^k\}_{k=1}^K$. Given $\vareps>0$, and $\{\beta_k\}$,$\{\rho_k\}$ set according to either Setting \ref{set-penalty} or Setting \ref{set-ialm}, we can choose $\{\vareps_k\}$ to minimize $T_K$ subject to the condition in \eqref{eq:req-eps}. 


\begin{equation}\label{eq:const-eps}
\vareps_k=\frac{\vareps }{2}\frac{C_\vareps}{C_\beta},\,\forall \, 0\le k<K,
\end{equation}

