\begin{theorem}[Iteration complexity with constant penalty and constant error]\label{thm:it-comp-const}
For any given $\vareps>0$, let $K$ be a positive integer number and $C_\beta, C_\vareps$ two positive real numbers. Set $\{\beta_k\}$ and $\{\rho_k\}$ according to Setting \ref{set-penalty} and $\{\vareps_k\}$ by \eqref{eq:const-eps}. Let $\bar{\vx}^K$ be given in \eqref{eq:barx-K}. Then 
\begin{subequations}\label{eq:error-barx-K}
\begin{align}
\big|f_0(\bar{\vx}^{K})-f_0(\vx^*)\big| \le \frac{\vareps\big(2\|\vy^*\|^2+ 2\|\vz^*\|^2\big)}{C_\beta}+\frac{\vareps}{2}\frac{C_\vareps}{C_\beta},\label{eq:error-barx-K-obj}\\
\|\vA\bar{\vx}^{K}-\vb\| + \big\| [\vf(\bar{\vx}^{K})]_+ \big\|\le  \frac{\vareps\big[(1+\|\vy^*\|)^2+ (1+\|\vz^*\|)^2\big]}{2C_\beta}+\frac{\vareps}{2}\frac{C_\vareps}{C_\beta}.\label{eq:error-barx-K-res}
\end{align}
\end{subequations}
Assume $\mu\le \frac{L_0}{4}$. Then Algorithm \ref{alg:ialm} can produce $\bar{\vx}^K$ by evaluating gradients of $g, f_i, \,i\in [m]$ in at most $T_K$ times, where
\begin{equation}\label{eq:T-penaly-cvx}
T_K\le \left\lceil2DK\sqrt{\frac{C_\beta}{C_\vareps}}\left(\sqrt{\frac{L_*}{\vareps}}+\frac{1}{\vareps}\sqrt{\frac{C_\beta H}{K}}\right)+K\right\rceil, \text{ if }\mu=0,
\end{equation}
and
\begin{equation}\label{eq:T-penaly-strcvx}
T_K\le \left\lceil2K\left(\sqrt{\frac{L_*}{\mu}}+\sqrt{\frac{C_\beta H}{\mu K\vareps}}\right)\log\left(\frac{D^2 C_\beta}{C_\vareps}\big(\frac{L_*+\mu}{\vareps}+\frac{C_\beta H}{K\vareps^2}\big)\right) + K\right\rceil, \text{ if }\mu>0.
\end{equation}

\end{theorem}

