\begin{lemma}\label{lem:pre-rate}
Assume $(\vx^*,\vy^*,\vz^*)$ satisfies the KKT conditions in \eqref{eq:kkt}. Let $\bar{\vx}$ be a point such that for any $\vy$ and any $\vz\ge\vzero$,
\begin{equation}\label{eq:pre-rate-cond}
f_0(\bar{\vx})-f_0(\vx^*)+ \vy^\top (\vA\bar{\vx}-\vb) +\sum_{i=1}^m z_i f_i(\bar{\vx}) \le \alpha + c_1\|\vy\|^2+c_2\|\vz\|^2,
\end{equation}
where $\alpha$ and $c_1, c_2$ are nonnegative constants independent of $\vy$ and $\vz$. Then
\begin{align}
-\left(\alpha + 4c_1\|\vy^*\|^2+ 4c_2\|\vz^*\|^2\right)\le f_0(\bar{\vx})-f_0(\vx^*)\le \alpha,\label{eq:pre-rate-obj}\\
\|\vA\bar{\vx}-\vb\| + \big\|[\vf(\bar{\vx})]_+\big\| \le \alpha + c_1\big(1+\|\vy^*\|\big)^2 + c_2\big(1+\|\vz^*\|\big)^2. \label{eq:pre-rate-res}
\end{align}
\end{lemma}

\begin{proof}
Letting $\vy=\vzero$ and $\vz=\vzero$ in \eqref{eq:pre-rate-cond} gives the second inequality in \eqref{eq:pre-rate-obj}.
For any nonnegative $\gamma_y$ and $\gamma_z$, we let 
$$\vy=\gamma_y\frac{\vA\bar{\vx}-\vb}{\|\vA\bar{\vx}-\vb\|},\quad \vz = \gamma_z \frac{[\vf(\bar{\vx})]_+}{\big\|[\vf(\bar{\vx})]_+\big\|}$$ %z_i = \gamma_i \frac{[f_i(\bar{\vx})]_+}{|f_i(\bar{\vx})|}, \forall i\in [m]$$
and have from \eqref{eq:pre-rate-cond} by using the convention $\frac{0}{0}=0$ that
\begin{align}\label{eq:pre-rate-ineq2}
f_0(\bar{\vx})-f_0(\vx^*) +\gamma_y \|\vA\bar{\vx}-\vb\| + \gamma_z\big\|[\vf(\bar{\vx})]_+\big\|
\le  \alpha + c_1\gamma_y^2+ c_2\gamma_z^2.
%f_0(\bar{\vx})-f_0(\vx^*) +\gamma_y \|\vA\bar{\vx}-\vb\| + \sum_{i=1}^m \gamma_i [f_i(\bar{\vx})]_+
%\le  \alpha + c_1\gamma_y^2+ c_2\sum_{i=1}^m\gamma_i^2.
\end{align}

Noting 
\begin{equation}\label{eq:pre-rate-ineq3}
-\langle \vy^*, \vA\bar{\vx}-\vb\rangle \ge -\|\vy^*\|\cdot\|\vA\bar{\vx}-\vb\|,\quad - \sum_{i=1}^mz_i^* f_i(\bar{\vx}) \ge - \|\vz^*\|\cdot \big\|[\vf(\bar{\vx})]_+\big\|,
\end{equation} we have from \eqref{eq:opt} and \eqref{eq:pre-rate-ineq2} that
\begin{align*}
(\gamma_y-\|\vy^*\|) \|\vA\bar{\vx}-\vb\| + (\gamma_z -\|\vz^*\|)\|[\vf(\bar{\vx})]_+\big\|
\le  \alpha + c_1\gamma_y^2+ c_2\gamma_z^2
\end{align*}
In the above inequality, letting $\gamma_y=1+\|\vy^*\|$ and $\gamma_z = 1+\|\vz^*\|$ gives \eqref{eq:pre-rate-res}, and letting $\gamma_y=2\|\vy^*\|$ and $\gamma_z = 2\|\vz^*\|$ gives the first inequality in \eqref{eq:pre-rate-obj} by \eqref{eq:opt} and \eqref{eq:pre-rate-ineq3}.
\end{proof}

\begin{theorem}\label{thm:rate-apg}
Let $\{\vx^k \}$ be the sequence generated from Algorithm \ref{alg:apg}. Assume $\vx^*$ to be a minimizer of \eqref{eq:comp-prob}. The following results holds:
\begin{enumerate}
\item If $\mu=0$ and $\alpha_0=1$, then
\begin{equation}\label{eq:optimal-rate-cvx}
\phi(\vx^k) + \psi(\vx^k) - \phi(\vx^*)-\psi(\vx^*) \le \frac{2L_\phi\|\vx^0-\vx^*\|^2}{k^2},\,\forall k\ge1.
\end{equation}
\item If $\mu >0$ and $\alpha_0=\sqrt{\frac{\mu}{L_\phi}}$, then
\begin{equation}\label{eq:optimal-rate-scvx}
\phi(\vx^k)-\phi(\vx^*)\le \frac{(L_\phi+\mu)\|\vx^0-\vx^*\|^2}{2}\left(1-\sqrt{\frac{\mu}{L_\phi}}\right)^k,\,\forall k\ge1.
\end{equation}
\end{enumerate}
\end{theorem}

\begin{lemma}\label{lem:multiplier}
Let $\vy$ and $\vz$ be updated by \eqref{eq:alm-y} and \eqref{eq:alm-z} respectively. Then for any $k$, it holds
\begin{align}
\frac{1}{2\rho_k}\big[\|\vy^{k+1} -\vy\|^2-\|\vy^k -\vy\|^2+\|\vy^{k+1} -\vy^k \|^2\big] - \langle \vy^{k+1} -\vy, \vr^{k+1}\rangle = &~ 0,\label{eq:alm-yterm}\\
\frac{1}{2\rho_k}\big[\|\vz^{k+1} -\vz\|^2-\|\vz^k  -\vz\|^2+\|\vz^{k+1} -\vz^k  \|^2\big]- \sum_{i=1}^m (z_i^{k+1}-z_i)\cdot\max\big(-\frac{z_i^k}{\beta_k}, f_i(\vx^{k+1})\big)=& ~0,\label{eq:alm-zterm}
\end{align}
where $\vr^k =\vA\vx^k -\vb$.
\end{lemma}

\begin{proof}
Using the equality $2\vu^\top \vv = \|\vu\|^2 - \|\vu-\vv\|^2 + \|\vv\|^2$, we have the results from the updates \eqref{eq:alm-y} and \eqref{eq:alm-z}.
\end{proof}

\begin{lemma}\label{lem:ineq-z}
For any $\vz\ge\vzero$, we have
\begin{align}\label{eq:alm-ineq-z}
&\sum_{i=1}^m\big([z_i^k+\beta_k f_i(\vx^{k+1})]_+-z_i\big) f_i(\vx^{k+1})- \sum_{i=1}^m (z_i^{k+1}-z_i)\cdot\max\big(-\frac{z_i^k}{\beta_k}, f_i(\vx^{k+1})\big)\nonumber\\
\ge&\frac{1}{\rho_k^2}(\beta_k-\rho_k)\|\vz^{k+1} -\vz^k  \|^2.
\end{align}
\end{lemma}

\begin{proof}
Denote 
\begin{equation}\label{eq:setIk}
I_+^k=\{i\in [m]: z_i^k + \beta_k f_i(\vx^{k+1}) \ge 0\},\quad I_-^k=[m]\backslash I_+^k.
\end{equation}
 Then 
\begin{align*}
&\text{the left hand side of \eqref{eq:alm-ineq-z}}\\
=&\sum_{i\in I_+^k}\left[(z_i^k-z_i)f_i(\vx^{k+1})+\beta_k[f_i(\vx^{k+1})]^2-\big(z_i^k+\rho_k f_i(\vx^{k+1})-z_i\big)f_i(\vx^{k+1})\right]\\
&+\sum_{i\in I_-^k}\left[-z_i f_i(\vx^{k+1})-\big(z_i^k-\frac{\rho_k z_i^k}{\beta_k}-z_i\big)\big(-\frac{z_i^k}{\beta_k}\big)\right]\\
=&(\beta_k-\rho_k)\sum_{i\in I_+^k}[f_i(\vx^{k+1})]^2+\sum_{i\in I_-^k}\left[-z_i \big(f_i(\vx^{k+1})+\frac{z_i^k}{\beta_k}\big)+\frac{1}{\beta_k^2}(\beta_k-\rho_k)(z_i^k)^2\right]\\
\ge& (\beta_k-\rho_k)\sum_{i\in I_+^k}[f_i(\vx^{k+1})]^2 +\frac{1}{\beta_k^2}(\beta_k-\rho_k)\sum_{i\in I_-^k}(z_i^k)^2\\
=&\frac{1}{\rho_k^2}(\beta_k-\rho_k)\|\vz^{k+1} -\vz^k  \|^2,
\end{align*}
where the inequality follows from $z_i\ge0$ and $f_i(\vx^{k+1})+\frac{z_i^k}{\beta_k}\le 0,\,\forall i\in I_-^k$, and the last equality holds due to the update \eqref{eq:alm-z}.
\end{proof}

\begin{theorem}[One-iteration progress of iALM]\label{thm:1iter-ialm}
Let $\{(\vx^k ,\vy^k ,\vz^k  )\}$ be the sequence generated from Algorithm \ref{alg:ialm}. Then for any $\vx\in\cX$ such that $\vA\vx=\vb$ and $f_i(\vx)\le 0,\,\forall i\in [m]$, any $\vy$, and any $\vz\ge\vzero$, it holds that
\begin{align}\label{eq:ialm-ineq2}
&f_0(\vx^{k+1})-f_0(\vx) +\vy^\top \vr^{k+1} + \sum_{i=1}^m z_i f_i(\vx^{k+1})+\frac{\beta_k-\rho_k}{2}\|\vr^{k+1}\|^2\cr
&+\frac{\beta_k-\rho_k}{2\rho_k^2}\|\vz^{k+1} -\vz^k  \|^2+\frac{1}{2\rho_k}\|\vy^{k+1} -\vy\|^2 + \frac{1}{2\rho_k}\|\vz^{k+1} -\vz\|^2\cr
\le & \frac{1}{2\rho_k}\|\vy^k -\vy\|^2+ \frac{1}{2\rho_k}\|\vz^k  -\vz\|^2+\vareps_k.
\end{align}
\end{theorem}

\begin{proof}
From \eqref{eq:ialm-x}, it follows that for any $\vx$ such that $\vA\vx=\vb$,
\begin{equation}\label{eq:ialm-1st}
f_0(\vx^{k+1})+\langle \vy^k , \vr^{k+1}\rangle +\frac{\beta_k}{2}\|\vr^{k+1}\|^2+\Psi_{\beta_k}(\vx^{k+1},\vz^k  )-f_0(\vx)-\Psi_{\beta_k}(\vx,\vz^k  )\le\vareps_k.
\end{equation}
Since $\langle \vy^k , \vr^{k+1}\rangle=\langle \vy^{k+1} -\vy, \vr^{k+1}\rangle + \langle \vy, \vr^{k+1}\rangle -\rho_k\|\vr^{k+1}\|^2$, by adding \eqref{eq:alm-yterm} and \eqref{eq:alm-zterm} to the above inequality, we have 
\begin{align}\label{eq:ialm-ineq1}
&f_0(\vx^{k+1})-f_0(\vx) +\vy^\top \vr^{k+1} + \sum_{i=1}^m z_i f_i(\vx^{k+1})+\sum_{i=1}^m\left([z_i^k+\beta_k f_i(\vx^{k+1})]_+-z_i\right)f_i(\vx^{k+1})\cr
&+\big(\frac{\beta_k}{2}-\rho_k\big)\|\vr^{k+1}\|^2+\Psi_{\beta_k}(\vx^{k+1},\vz^k  )-\sum_{i=1}^m[z_i^k+\beta_k f_i(\vx^{k+1})]_+f_i(\vx^{k+1})-\Psi_{\beta_k}(\vx,\vz^k  )\cr
&+\frac{1}{2\rho_k}\big[\|\vy^{k+1} -\vy\|^2-\|\vy^k -\vy\|^2+\|\vy^{k+1} -\vy^k \|^2\big] \cr
&+\frac{1}{2\rho_k}\big[\|\vz^{k+1} -\vz\|^2-\|\vz^k  -\vz\|^2+\|\vz^{k+1} -\vz^k  \|^2\big]- \sum_{i=1}^m (z_i^{k+1}-z_i)\cdot\max\big(-\frac{z_i^k}{\beta_k}, f_i(\vx^{k+1})\big)\cr
\le & \vareps_k.
\end{align}

Note that
\begin{align}\label{eq:ialm-ineq3}
&\Psi_{\beta_k}(\vx^{k+1},\vz^k  )-\sum_{i=1}^m[z_i^k+\beta_k f_i(\vx^{k+1})]_+f_i(\vx^{k+1})\cr
=&\sum_{i\in I_+^k}\left[z_i^k f_i(\vx^{k+1}) +\frac{\beta_k}{2}[f_i(\vx^{k+1})]^2-[z_i^k +\beta_k f_i(\vx^{k+1})]f_i(\vx^{k+1})\right]+\sum_{i\in I_-^k}\left[-\frac{(z_i^k)^2}{2\beta_k}\right]\cr
=&-\sum_{i\in I_+^k}\frac{\beta_k}{2}[f_i(\vx^{k+1})]^2-\sum_{i\in I_-^k}\frac{(z_i^k)^2}{2\beta_k}\cr
=&-\frac{\beta_k}{2\rho_z^2}\|\vz^{k+1} -\vz^k  \|^2,
\end{align}
where the sets $I_+^k$ and $I_-^k$ are defined in \eqref{eq:setIk}.
In addition, if $f_i(\vx)\le 0,\,\forall i\in [m]$, then $\Psi_{\beta_k}(\vx,\vz^k  )\le 0.$ Hence, plugging \eqref{eq:alm-ineq-z} and \eqref{eq:ialm-ineq3} into \eqref{eq:ialm-ineq1} yields \eqref{eq:ialm-ineq2}.
\end{proof}

\begin{theorem}[Ergodic convergence rate of iALM]\label{thm:ialm-rate}
Under Assumptions \ref{assump-kkt} and \ref{assump-wd-ialm}, let $\{(\vx^k ,\vy^k ,\vz^k  )\}$ be the sequence generated from Algorithm \ref{alg:ialm} with $\vy^0=\vzero, \vz^0 = \vzero$ and $0<\rho_k\le\beta_k,\,\forall k$. Then
\begin{subequations}\label{eq:ialm-rate}
\begin{align}
\big|f_0(\bar{\vx}^{K})-f_0(\vx^*)\big| \le \frac{1}{\sum_{t=0}^{K-1}\rho_t}\left(2\|\vy^*\|^2+ 2\|\vz^*\|^2+\sum_{k=0}^{K-1}\rho_k\vareps_k\right),\label{eq:ialm-rate-obj}\\
\|\vA\bar{\vx}^{K}-\vb\| + \big\| [\vf(\bar{\vx}^{K})]_+\big\| \le  \frac{1}{\sum_{t=0}^{K-1}\rho_t}\left(\frac{(1+\|\vy^*\|)^2}{2}+ \frac{(\|1+\|\vz^*\|)^2}{2}+\sum_{k=0}^{K-1}\rho_k\vareps_k\right),\label{eq:ialm-rate-res}
\end{align}
\end{subequations}
where 
\begin{equation}\label{eq:barx-K}
\bar{\vx}^{K}=\frac{\sum_{t=0}^{K-1}\rho_t\vx^{t+1} }{\sum_{t=0}^{K-1}\rho_t}.
\end{equation}
\end{theorem}

\begin{proof}
Since $\rho_k\le \beta_k$, the two terms $\frac{\beta_k-\rho_k}{2}\|\vr^{k+1}\|^2$ and 
$\frac{\beta_k-\rho_k}{2\rho_k^2}\|\vz^{k+1} -\vz^k  \|^2$ are nonnegative. Dropping them and multiplying $\rho_k$ to both sides of \eqref{eq:ialm-ineq2} yields 
\begin{align}\label{eq:ialm-ineq2-1}
&\rho_k\left[f_0(\vx^{k+1})-f_0(\vx) +\vy^\top  \vr^{k+1} + \sum_{i=1}^m z_i f_i(\vx^{k+1})\right]+\frac{1}{2}\|\vy^{k+1} -\vy\|^2 + \frac{1}{2}\|\vz^{k+1} -\vz\|^2\cr
\le & \frac{1}{2}\|\vy^k -\vy\|^2+ \frac{1}{2}\|\vz^k  -\vz\|^2+\rho_k\vareps_k.
\end{align}

Summing up \eqref{eq:ialm-ineq2} with $\vx=\vx^*$ gives
\begin{align}\label{eq:ialm-ineq2-2}
&\sum_{k=0}^{K-1}\rho_k\left[f_0(\vx^{k+1})-f_0(\vx^*) +\vy^\top \vr^{k+1} + \sum_{i=1}^m z_i f_i(\vx^{k+1})\right]+\frac{1}{2}\|\vy^{K}-\vy\|^2 + \frac{1}{2}\|\vz^{K}-\vz\|^2\cr
\le & \frac{1}{2}\|\vy^0-\vy\|^2+ \frac{1}{2}\|\vz^0-\vz\|^2+\sum_{k=0}^{K-1}\rho_k\vareps_k.
\end{align}
By the convexity of $f_i$'s and the nonnegativity of $\vz$, we have
\begin{align*}
&~f_0(\bar{\vx}^{K})-f_0(\vx^*) +\vy^\top  (\vA\bar{\vx}^{K}-\vb) + \sum_{i=1}^m z_i f_i(\bar{\vx}^{K})\\
\le &~\frac{1}{\sum_{t=0}^{K-1}\rho_t} \sum_{k=0}^{K-1}\rho_k\left[f_0(\vx^{k+1})-f_0(\vx^*) +\vy^\top  \vr^{k+1} + \sum_{i=1}^m z_i f_i(\vx^{k+1})\right],
\end{align*}
which together with \eqref{eq:ialm-ineq2-2} implies
$$f_0(\bar{\vx}^{K})-f_0(\vx^*) +\vy^\top  (\vA\bar{\vx}^{K}-\vb) + \sum_{i=1}^m z_i f_i(\bar{\vx}^{K})
\le  \frac{1}{\sum_{t=0}^{K-1}\rho_t}\left(\frac{1}{2}\|\vy\|^2+ \frac{1}{2}\|\vz\|^2+\sum_{k=0}^{K-1}\rho_k\vareps_k\right).$$
The results thus follow from Lemma \ref{lem:pre-rate} with 
$$\alpha=\frac{\sum_{k=0}^{K-1}\rho_k\vareps_k}{\sum_{k=0}^{K-1}\rho_k},\ c_1=\frac{1}{2\sum_{k=0}^{K-1}\rho_k},\ c_2=\frac{1}{2\sum_{k=0}^{K-1}\rho_k},$$
and we complete the proof.
\end{proof}

The following results are easy to show from the Lipschitz differentiability of $g$ and $f_i,\, i\in [m]$.
\begin{proposition}\label{prop-lip}
Assume \eqref{eq:lip-g}, \eqref{eq:lip-f}, and the boundedness of $\dom(h)\cap \cX$. Then there exist constants $B_1,\ldots, B_m$ such that
\begin{subequations}\label{eq:lip}
\begin{align}
\max\big(|f_i(\vx)|, \|\nabla f_i(\vx)\|\big) \le B_i, \,& \forall \vx\in \dom(h)\cap\cX, \forall i\in [m],\label{eq:bd-f}\\
|f_i(\hat{\vx})-f_i(\tilde{\vx})| \le B_i\|\hat{\vx}-\tilde{\vx}\|, \, & \forall \hat{\vx}, \tilde{\vx} \in \dom(h)\cap\cX, \forall i\in [m].\label{eq:lip-fv}
\end{align}
\end{subequations}
\end{proposition}

\begin{lemma}\label{lem:lip}
Assume \eqref{eq:lip-g}, \eqref{eq:lip-f}, and the boundedness of $\dom(h)\cap \cX$. Let $B_i$'s be given in Proposition \ref{prop-lip}. Then $\nabla_\vx F_{\beta_k}(\vx,\vy^k,\vz^k)$ is Lipschitz continuous on $\dom(h)\cap\cX$ in terms of $\vx$ with constant
\begin{equation}\label{eq:def-Lz}
L(\vz^k) = L_0+\beta_k\|\vA^\top \vA\|+\sum_{i=1}^m \big(\beta_k B_i(B_i+L_i)+L_i|z_i^k|\big).
\end{equation}
\end{lemma}

\begin{proof}
For ease of description, we let $\beta=\beta_k$ and $(\vy,\vz)=(\vy^k,\vz^k)$ in the proof. First we notice that $\frac{\partial}{\partial u}\psi_\beta(u,v)=[\beta u+v]_+$, and thus for any $v$,
$$\left|\frac{\partial}{\partial u}\psi_\beta(\hat{u},v)-\frac{\partial}{\partial u}\psi_\beta(\tilde{u},v)\right|\le \beta|\hat{u}-\tilde{u}|,\,\forall \hat{u},\tilde{u}.$$
Let $h_i(x,z_i) = \psi_\beta(f_i(\vx),z_i),\,i=1,\ldots,m$. Then
\begin{align*}
&\|\nabla_\vx h_i(\hat{\vx},z_i)-\nabla_\vx h_i(\tilde{\vx},z_i)\|\\
=&\big\|\frac{\partial}{\partial u}\psi_\beta(f_i(\hat{\vx}),z_i)\nabla f_i(\hat{\vx})-\frac{\partial}{\partial u}\psi_\beta(f_i(\tilde{\vx}),z_i)\nabla f_i(\tilde{\vx})\big\|\\
\le&\big\|\frac{\partial}{\partial u}\psi_\beta(f_i(\hat{\vx}),z_i)\nabla f_i(\hat{\vx})-\frac{\partial}{\partial u}\psi_\beta(f_i(\tilde{\vx}),z_i)\nabla f_i(\hat{\vx})\big\|\\
&+\big\|\frac{\partial}{\partial u}\psi_\beta(f_i(\tilde{\vx}),z_i)\nabla f_i(\hat{\vx})-\frac{\partial}{\partial u}\psi_\beta(f_i(\tilde{\vx}),z_i)\nabla f_i(\tilde{\vx})\big\|\\
\le& \beta|f_i(\hat{\vx})-f_i(\tilde{\vx})|\cdot\|\nabla f_i(\hat{\vx})\|+\big|\frac{\partial}{\partial u}\psi_\beta(f_i(\tilde{\vx}),z_i)\big|\cdot\|\nabla f_i(\hat{\vx})-\nabla f_i(\tilde{\vx})\|\\
\le & \beta B_i^2\|\hat{\vx}-\tilde{\vx}\|+ L_i(\beta B_i + |z_i|) \|\hat{\vx}-\tilde{\vx}\|.
\end{align*}
Hence,
\begin{align*}
&\|\nabla_\vx F_\beta(\hat{\vx},\vy,\vz)-\nabla_\vx F_\beta(\tilde{\vx},\vy,\vz)\|\\
\le& \|\nabla g(\hat{\vx})-\nabla g(\tilde{\vx})\|+\beta\|\vA^\top \vA(\hat{\vx}-\tilde{\vx})\| + \sum_{i=1}^m \|\nabla_\vx h_i(\hat{\vx},z_i)-\nabla_\vx h_i(\tilde{\vx},z_i)\|\\
\le & \left(L_0+\beta\|\vA^\top \vA\|+\sum_{i=1}^m \big[\beta B_i^2+ L_i(\beta B_i + |z_i|)\big]\right)\|\hat{\vx}-\tilde{\vx}\|,
\end{align*}
which completes the proof.
\end{proof}

Therefore, letting
$\phi(\vx) = F_{\beta_k}(\vx,\vy^k ,\vz^k  )$ and $\psi(\vx) = h(\vx)+\iota_\cX(\vx),$
we can apply Nesterov's optimal first-order method in Algorithm \ref{alg:apg} to find $\vx^{k+1}$ in \eqref{eq:ialm-x}. From Theorem \ref{thm:rate-apg}, we have the following results. Note that if the strong convexity constant $\mu=0$, the problem is just convex.


\begin{lemma}\label{lem:sub-iter}
Assume that $g$ is strongly convex with modulus $\mu\ge0$. Given $\vareps_k>0$, if we start from $\vx^k $ and run Algorithm \ref{alg:apg}, then at most $t_k$ iterations are needed to produce $\vx^{k+1}$ such that \eqref{eq:ialm-x} holds,
where 
\begin{equation}\label{eq:tk-cvx}
t_k = \left\{
