\left\lceil\dfrac{\dist(\vx^k ,\cX_k^*)\sqrt{2L(\vz^k  )}}{\sqrt{\vareps_k}}\right\rceil, & \text{ if }\mu=0,\\[0.5cm]
\left\lceil\dfrac{\log\left(\frac{L(\vz^k  )+\mu}{2\vareps_k}[\dist(\vx^k ,\cX_k^*)]^2\right)}{\log1/\big(1-\sqrt{\frac{\mu}{L(\vz^k  )}}\big)}\right\rceil, & \text{ if }\mu>0,
\end{array}
\right.
\end{equation}
and $\cX_k^*$ denotes the set of optimal solutions to $\min_{\vx\in \cX}\cL_{\beta_k}(\vx,\vy^k ,\vz^k  )$.
%with
%$$\phi(\vx) = F_\beta(x,\vy^k ,\vz^k  ),\quad \psi(\vx) = h(\vx)+\iota_\cX(\vx),$$ then we have
