%\cL_\beta(\vx^{k+1},\vy^k ,\vz^k  )-\min_{x\in \cX}\cL_\beta(x,\vy^k ,\vz^k  ) \le \frac{2L(\vz^k  )[\dist(\vx^k ,\cX_k^*)]^2}{t_k^2},
