\end{lemma}

\begin{lemma}\label{lem:bd-z-Lz}
Let $\{(\vx^k,\vy^k,\vz^k)\}_{k=0}^K$ be the sequence generated from Algorithm \ref{alg:ialm} with $\{\beta_k\}$ and $\{\rho_k\}$ set according to either Setting \ref{set-penalty} or Setting \ref{set-ialm}. If $\vy^0=\vzero, \vz^0=\vzero$, and $\vareps_k$'s are chosen such that 
\begin{equation}\label{eq:req-eps}
\sum_{k=0}^{K-1}\rho_k\vareps_k\le \frac{C_\vareps}{2},
\end{equation}
 then
\begin{align}\label{eq:bd-Lzk}
L(\vz^k)\le L_*+\beta_k H,\,\forall \, 0\le k\le K,
\end{align}
where 
$$ H=\|\vA^\top \vA\|+ \sum_{i=1}^m  B_i(B_i+L_i),\ L_*=L_0+ \|\vell\| \left(\|\vy^*\|+2\|\vz^*\|+\sqrt{C_\vareps}\right)$$
and $\vell$ is given in \eqref{eq:vec-ell}.
\end{lemma}

\begin{proof}
Letting $(\vx,\vy,\vz)=(\vx^*,\vy^*,\vz^*)$ in \eqref{eq:ialm-ineq2-1} and using \eqref{eq:opt}, we have 
$$\frac{1}{2}\|\vy^{k+1} -\vy^*\|^2 + \frac{1}{2}\|\vz^{k+1} -\vz^*\|^2
\le  \frac{1}{2}\|\vy^k -\vy^*\|^2+ \frac{1}{2}\|\vz^k  -\vz^*\|^2+\rho_k\vareps_k.$$
Summing the above inequality yields 
$$\frac{1}{2}\|\vy^{k}-\vy^*\|^2 + \frac{1}{2}\|\vz^{k}-\vz^*\|^2
\le  \frac{1}{2}\|\vy^0-\vy^*\|^2+ \frac{1}{2}\|\vz^0-\vz^*\|^2+\sum_{t=0}^{k-1}\rho_t\vareps_t, \, \forall \, 0\le k \le K,$$
which implies
$$\|\vz^k  \| \le \|\vz^*\|+\sqrt{\|\vy^0-\vy^*\|^2+\|\vz^0-\vz^*\|^2+2\sum_{t=0}^{k-1}\rho_t\vareps_t}.$$
Since $\|\vu\|\le \|\vu\|_1$ for any vector $\vu$, we have from the above inequality that
\begin{equation}\label{eq:bd-zk0}
\|\vz^k  \| \le  \|\vz^*\|+\|\vy^0-\vy^*\|+\|\vz^0-\vz^*\|+\sqrt{2\sum_{t=0}^{K-1}\rho_t\vareps_t},\, \forall \, 0\le k \le K.
\end{equation}

Hence, if $\vy^0=\vzero$ and $\vz^0=\vzero$, and \eqref{eq:req-eps} holds, it follows from the above inequality that
\begin{equation}\label{eq:bd-zk}
\|\vz^k  \| \le  \|\vy^*\|+2\|\vz^*\|+\sqrt{C_\vareps},\, \forall \, 0\le k \le K,
\end{equation}
By the Cauchy-Schwartz inequality, we have from \eqref{eq:def-Lz} that for any $0\le k\le K$,
$$L(\vz^k  ) \le L_0+\beta_k H + \|\vz^k  \|\cdot\|\vell\|$$
which together with \eqref{eq:bd-zk} gives the result in \eqref{eq:bd-Lzk}.
\end{proof}

\begin{proof}
The results in \eqref{eq:error-barx-K} directly follows from Theorem \ref{thm:ialm-rate} and the settings of $\{\beta_k\}$, $\{\rho_k\}$, and $\{\vareps_k\}$. For the total number of gradient evaluations, we use the inequalities in \eqref{eq:tk-cvx}. First, for the case of $\mu=0$, from the first inequality of \eqref{eq:tk-cvx} and the parameter setting, it follows that the total number of gradient evaluations
\begin{equation}\label{eq:total-grad-cvx-adp1}
T_K\le \sum_{k=0}^{K-1}\frac{\dist(\vx^k ,\cX_k^*)\sqrt{2(L_*+\frac{C_\beta H}{K\vareps})}}{\sqrt{\vareps/2}\sqrt{C_\vareps/C_\beta}}+K.
\end{equation}
Since $\sqrt{a+b}\le \sqrt{a}+\sqrt{b}$ for any two nonnegative numbers $a,b$, we have from the above inequality and by noting $\dist(\vx^k ,\cX_k^*)\le D$ that
\begin{align*}
T_K \le 2D\sqrt{\frac{C_\beta}{C_\vareps}}\sum_{k=0}^{K-1}\frac{\sqrt{L_*}+\sqrt{\frac{C_\beta H}{K\vareps}}}{\sqrt{\vareps}}+K=2DK\sqrt{\frac{C_\beta}{C_\vareps}}\left(\sqrt{\frac{L_*}{\vareps}}+\frac{1}{\vareps}\sqrt{\frac{C_\beta H}{K}}\right)+K,
\end{align*}
which gives \eqref{eq:T-penaly-cvx}.

For the case of $\mu>0$, we first note that for any $0<a\le1$, it holds $\log(1+a)\ge a-\frac{a^2}{2}\ge\frac{a}{2}$. Hence, if $\mu\le \frac{L_0}{4}$, we have $\mu\le \frac{L(\vz^k)}{4}$ and $\frac{\sqrt{\mu/L(\vz^k)}}{1-\sqrt{\mu/L(\vz^k)}}\le 1$. Therefore,
$$\log\frac{1}{1-\sqrt{\mu/L(\vz^k)}}=\log\left(1+\frac{\sqrt{\mu/L(\vz^k)}}{1-\sqrt{\mu/L(\vz^k)}}\right)\ge \frac{1}{2}\frac{\sqrt{\mu/L(\vz^k)}}{1-\sqrt{\mu/L(\vz^k)}},$$ and thus
\begin{equation}\label{eq:bd-denom}
\frac{1}{\log\frac{1}{1-\sqrt{\mu/L(\vz^k)}}}\le 2\sqrt{\frac{L(\vz^k)}{\mu}}\left(1-\sqrt{\mu/L(\vz^k)}\right) \le 2\sqrt{\frac{L(\vz^k)}{\mu}}.
\end{equation} Using the above inequality and the second inequality of \eqref{eq:tk-cvx}, we have that the total number of gradient evaluations
\begin{equation}
T_K\le  \sum_{k=0}^{K-1}2\sqrt{\frac{L_*+\frac{C_\beta H}{K\vareps}}{\mu}}\log\left(\frac{L_*+\frac{C_\beta H}{K\vareps}+\mu}{\vareps C_\vareps/C_\beta}[\dist(\vx^k ,\cX_k^*)]^2\right)+K.\label{eq:total-grad-scvx-adp1}
\end{equation}
Since $\sqrt{L_*+\frac{C_\beta H}{K\vareps}}\le \sqrt{L_*}+\sqrt{\frac{C_\beta H}{K\vareps}}$ and $\dist(\vx^k ,\cX_k^*)\le D$, the above inequality implies \eqref{eq:T-penaly-strcvx}.
This completes the proof.
\end{proof}

