\begin{lemma}\label{lem:ineq-z}
For any $\vz\ge\vzero$, we have
\begin{align}\label{eq:alm-ineq-z}
&\sum_{i=1}^m\big([z_i^k+\beta_k f_i(\vx^{k+1})]_+-z_i\big) f_i(\vx^{k+1})- \sum_{i=1}^m (z_i^{k+1}-z_i)\cdot\max\big(-\frac{z_i^k}{\beta_k}, f_i(\vx^{k+1})\big)\nonumber\\
\ge&\frac{1}{\rho_k^2}(\beta_k-\rho_k)\|\vz^{k+1} -\vz^k  \|^2.
\end{align}
\end{lemma}

\begin{proof}
Denote 
\begin{equation}\label{eq:setIk}
I_+^k=\{i\in [m]: z_i^k + \beta_k f_i(\vx^{k+1}) \ge 0\},\quad I_-^k=[m]\backslash I_+^k.
\end{equation}
 Then 
\begin{align*}
&\text{the left hand side of \eqref{eq:alm-ineq-z}}\\
=&\sum_{i\in I_+^k}\left[(z_i^k-z_i)f_i(\vx^{k+1})+\beta_k[f_i(\vx^{k+1})]^2-\big(z_i^k+\rho_k f_i(\vx^{k+1})-z_i\big)f_i(\vx^{k+1})\right]\\
&+\sum_{i\in I_-^k}\left[-z_i f_i(\vx^{k+1})-\big(z_i^k-\frac{\rho_k z_i^k}{\beta_k}-z_i\big)\big(-\frac{z_i^k}{\beta_k}\big)\right]\\
=&(\beta_k-\rho_k)\sum_{i\in I_+^k}[f_i(\vx^{k+1})]^2+\sum_{i\in I_-^k}\left[-z_i \big(f_i(\vx^{k+1})+\frac{z_i^k}{\beta_k}\big)+\frac{1}{\beta_k^2}(\beta_k-\rho_k)(z_i^k)^2\right]\\
\ge& (\beta_k-\rho_k)\sum_{i\in I_+^k}[f_i(\vx^{k+1})]^2 +\frac{1}{\beta_k^2}(\beta_k-\rho_k)\sum_{i\in I_-^k}(z_i^k)^2\\
=&\frac{1}{\rho_k^2}(\beta_k-\rho_k)\|\vz^{k+1} -\vz^k  \|^2,
\end{align*}
where the inequality follows from $z_i\ge0$ and $f_i(\vx^{k+1})+\frac{z_i^k}{\beta_k}\le 0,\,\forall i\in I_-^k$, and the last equality holds due to the update \eqref{eq:alm-z}.
\end{proof}

