\begin{theorem}[Ergodic convergence rate of iALM]\label{thm:ialm-rate}
Under Assumptions \ref{assump-kkt} and \ref{assump-wd-ialm}, let $\{(\vx^k ,\vy^k ,\vz^k  )\}$ be the sequence generated from Algorithm \ref{alg:ialm} with $\vy^0=\vzero, \vz^0 = \vzero$ and $0<\rho_k\le\beta_k,\,\forall k$. Then
\begin{subequations}\label{eq:ialm-rate}
\begin{align}
\big|f_0(\bar{\vx}^{K})-f_0(\vx^*)\big| \le \frac{1}{\sum_{t=0}^{K-1}\rho_t}\left(2\|\vy^*\|^2+ 2\|\vz^*\|^2+\sum_{k=0}^{K-1}\rho_k\vareps_k\right),\label{eq:ialm-rate-obj}\\
\|\vA\bar{\vx}^{K}-\vb\| + \big\| [\vf(\bar{\vx}^{K})]_+\big\| \le  \frac{1}{\sum_{t=0}^{K-1}\rho_t}\left(\frac{(1+\|\vy^*\|)^2}{2}+ \frac{(\|1+\|\vz^*\|)^2}{2}+\sum_{k=0}^{K-1}\rho_k\vareps_k\right),\label{eq:ialm-rate-res}
\end{align}
\end{subequations}
where 
\begin{equation}\label{eq:barx-K}
\bar{\vx}^{K}=\frac{\sum_{t=0}^{K-1}\rho_t\vx^{t+1} }{\sum_{t=0}^{K-1}\rho_t}.
\end{equation}
\end{theorem}

\begin{proof}
Since $\rho_k\le \beta_k$, the two terms $\frac{\beta_k-\rho_k}{2}\|\vr^{k+1}\|^2$ and 
$\frac{\beta_k-\rho_k}{2\rho_k^2}\|\vz^{k+1} -\vz^k  \|^2$ are nonnegative. Dropping them and multiplying $\rho_k$ to both sides of \eqref{eq:ialm-ineq2} yields 
\begin{align}\label{eq:ialm-ineq2-1}
&\rho_k\left[f_0(\vx^{k+1})-f_0(\vx) +\vy^\top  \vr^{k+1} + \sum_{i=1}^m z_i f_i(\vx^{k+1})\right]+\frac{1}{2}\|\vy^{k+1} -\vy\|^2 + \frac{1}{2}\|\vz^{k+1} -\vz\|^2\cr
\le & \frac{1}{2}\|\vy^k -\vy\|^2+ \frac{1}{2}\|\vz^k  -\vz\|^2+\rho_k\vareps_k.
\end{align}

Summing up \eqref{eq:ialm-ineq2} with $\vx=\vx^*$ gives
\begin{align}\label{eq:ialm-ineq2-2}
&\sum_{k=0}^{K-1}\rho_k\left[f_0(\vx^{k+1})-f_0(\vx^*) +\vy^\top \vr^{k+1} + \sum_{i=1}^m z_i f_i(\vx^{k+1})\right]+\frac{1}{2}\|\vy^{K}-\vy\|^2 + \frac{1}{2}\|\vz^{K}-\vz\|^2\cr
\le & \frac{1}{2}\|\vy^0-\vy\|^2+ \frac{1}{2}\|\vz^0-\vz\|^2+\sum_{k=0}^{K-1}\rho_k\vareps_k.
\end{align}
By the convexity of $f_i$'s and the nonnegativity of $\vz$, we have
\begin{align*}
&~f_0(\bar{\vx}^{K})-f_0(\vx^*) +\vy^\top  (\vA\bar{\vx}^{K}-\vb) + \sum_{i=1}^m z_i f_i(\bar{\vx}^{K})\\
\le &~\frac{1}{\sum_{t=0}^{K-1}\rho_t} \sum_{k=0}^{K-1}\rho_k\left[f_0(\vx^{k+1})-f_0(\vx^*) +\vy^\top  \vr^{k+1} + \sum_{i=1}^m z_i f_i(\vx^{k+1})\right],
\end{align*}
which together with \eqref{eq:ialm-ineq2-2} implies
$$f_0(\bar{\vx}^{K})-f_0(\vx^*) +\vy^\top  (\vA\bar{\vx}^{K}-\vb) + \sum_{i=1}^m z_i f_i(\bar{\vx}^{K})
\le  \frac{1}{\sum_{t=0}^{K-1}\rho_t}\left(\frac{1}{2}\|\vy\|^2+ \frac{1}{2}\|\vz\|^2+\sum_{k=0}^{K-1}\rho_k\vareps_k\right).$$
The results thus follow from Lemma \ref{lem:pre-rate} with 
$$\alpha=\frac{\sum_{k=0}^{K-1}\rho_k\vareps_k}{\sum_{k=0}^{K-1}\rho_k},\ c_1=\frac{1}{2\sum_{k=0}^{K-1}\rho_k},\ c_2=\frac{1}{2\sum_{k=0}^{K-1}\rho_k},$$
and we complete the proof.
\end{proof}

