\begin{proposition}\label{prop-lip}
Assume \eqref{eq:lip-g}, \eqref{eq:lip-f}, and the boundedness of $\dom(h)\cap \cX$. Then there exist constants $B_1,\ldots, B_m$ such that
\begin{subequations}\label{eq:lip}
\begin{align}
\max\big(|f_i(\vx)|, \|\nabla f_i(\vx)\|\big) \le B_i, \,& \forall \vx\in \dom(h)\cap\cX, \forall i\in [m],\label{eq:bd-f}\\
|f_i(\hat{\vx})-f_i(\tilde{\vx})| \le B_i\|\hat{\vx}-\tilde{\vx}\|, \, & \forall \hat{\vx}, \tilde{\vx} \in \dom(h)\cap\cX, \forall i\in [m].\label{eq:lip-fv}
\end{align}
\end{subequations}
\end{proposition}

\begin{lemma}\label{lem:lip}
Assume \eqref{eq:lip-g}, \eqref{eq:lip-f}, and the boundedness of $\dom(h)\cap \cX$. Let $B_i$'s be given in Proposition \ref{prop-lip}. Then $\nabla_\vx F_{\beta_k}(\vx,\vy^k,\vz^k)$ is Lipschitz continuous on $\dom(h)\cap\cX$ in terms of $\vx$ with constant
\begin{equation}\label{eq:def-Lz}
L(\vz^k) = L_0+\beta_k\|\vA^\top \vA\|+\sum_{i=1}^m \big(\beta_k B_i(B_i+L_i)+L_i|z_i^k|\big).
\end{equation}
\end{lemma}

\begin{proof}
For ease of description, we let $\beta=\beta_k$ and $(\vy,\vz)=(\vy^k,\vz^k)$ in the proof. First we notice that $\frac{\partial}{\partial u}\psi_\beta(u,v)=[\beta u+v]_+$, and thus for any $v$,
$$\left|\frac{\partial}{\partial u}\psi_\beta(\hat{u},v)-\frac{\partial}{\partial u}\psi_\beta(\tilde{u},v)\right|\le \beta|\hat{u}-\tilde{u}|,\,\forall \hat{u},\tilde{u}.$$
Let $h_i(x,z_i) = \psi_\beta(f_i(\vx),z_i),\,i=1,\ldots,m$. Then
\begin{align*}
&\|\nabla_\vx h_i(\hat{\vx},z_i)-\nabla_\vx h_i(\tilde{\vx},z_i)\|\\
=&\big\|\frac{\partial}{\partial u}\psi_\beta(f_i(\hat{\vx}),z_i)\nabla f_i(\hat{\vx})-\frac{\partial}{\partial u}\psi_\beta(f_i(\tilde{\vx}),z_i)\nabla f_i(\tilde{\vx})\big\|\\
\le&\big\|\frac{\partial}{\partial u}\psi_\beta(f_i(\hat{\vx}),z_i)\nabla f_i(\hat{\vx})-\frac{\partial}{\partial u}\psi_\beta(f_i(\tilde{\vx}),z_i)\nabla f_i(\hat{\vx})\big\|\\
&+\big\|\frac{\partial}{\partial u}\psi_\beta(f_i(\tilde{\vx}),z_i)\nabla f_i(\hat{\vx})-\frac{\partial}{\partial u}\psi_\beta(f_i(\tilde{\vx}),z_i)\nabla f_i(\tilde{\vx})\big\|\\
\le& \beta|f_i(\hat{\vx})-f_i(\tilde{\vx})|\cdot\|\nabla f_i(\hat{\vx})\|+\big|\frac{\partial}{\partial u}\psi_\beta(f_i(\tilde{\vx}),z_i)\big|\cdot\|\nabla f_i(\hat{\vx})-\nabla f_i(\tilde{\vx})\|\\
\le & \beta B_i^2\|\hat{\vx}-\tilde{\vx}\|+ L_i(\beta B_i + |z_i|) \|\hat{\vx}-\tilde{\vx}\|.
\end{align*}
Hence,
\begin{align*}
&\|\nabla_\vx F_\beta(\hat{\vx},\vy,\vz)-\nabla_\vx F_\beta(\tilde{\vx},\vy,\vz)\|\\
\le& \|\nabla g(\hat{\vx})-\nabla g(\tilde{\vx})\|+\beta\|\vA^\top \vA(\hat{\vx}-\tilde{\vx})\| + \sum_{i=1}^m \|\nabla_\vx h_i(\hat{\vx},z_i)-\nabla_\vx h_i(\tilde{\vx},z_i)\|\\
\le & \left(L_0+\beta\|\vA^\top \vA\|+\sum_{i=1}^m \big[\beta B_i^2+ L_i(\beta B_i + |z_i|)\big]\right)\|\hat{\vx}-\tilde{\vx}\|,
\end{align*}
which completes the proof.
\end{proof}

